#define Cache
using System;
using System.Collections.Generic;

namespace DayZ
{
    public class CCSafeNotificationCenter
    {
        private static CCSafeNotificationCenter s_sharedNotifCenter = null;

        private Dictionary<string, Dictionary<object, NotificationObserver>> m_observers = new Dictionary<string, Dictionary<object, NotificationObserver>>();

#if Cache
        private Dictionary<object, HashSet<string>> observerObjectKeyCache = new Dictionary<object, HashSet<string>>();
#endif

        private CCSafeNotificationCenter() { }

        ~CCSafeNotificationCenter()
        {
            foreach (var item in this.m_observers)
            {
                foreach (var i in item.Value)
                    i.Value.release();
            }
            this.m_observers.Clear();
#if Cache
            this.observerObjectKeyCache.Clear();
#endif
        }

        public static CCSafeNotificationCenter sharedNotificationCenter()
        {
            if (s_sharedNotifCenter == null)
                s_sharedNotifCenter = new CCSafeNotificationCenter();
            return s_sharedNotifCenter;
        }

        public void addObserver(object target, Action<object> selector, string name, object obj, bool trust = false)
        {
            if (!trust && this.observerExisted(target, name))
            {
                return;
            }

            NotificationObserver observer = new NotificationObserver(target, selector, name, obj);

            Dictionary<object, NotificationObserver> list = null;
            if (!this.m_observers.TryGetValue(name, out list))
            {
                list = new Dictionary<object, NotificationObserver>();
                this.m_observers.Add(name, list);
            }
            list.Add(target, observer);
#if Cache
            HashSet<string> targetKeys;
            if (!observerObjectKeyCache.TryGetValue(target, out targetKeys))
            {
                targetKeys = new HashSet<string>();
                observerObjectKeyCache.Add(target, targetKeys);
            }
            targetKeys.Add(name);
#endif
        }

        public void removeObserver(object target, string name, bool fromAll = false)
        {
            Dictionary<object, NotificationObserver> list = null;
            if (this.m_observers.TryGetValue(name, out list))
            {
                NotificationObserver o = null;
                list.TryGetValue(target, out o);
                if (o != null)
                {
                    list.Remove(target);
                    if (list.Count == 0)
                        this.m_observers.Remove(name);
                }
            }
#if Cache
            if (fromAll)
                return;
            HashSet<string> targetKeys;
            if (observerObjectKeyCache.TryGetValue(target, out targetKeys))
            {
                targetKeys.Remove(name);
                if (targetKeys.Count <= 0)
                    observerObjectKeyCache.Remove(target);
            }
#endif
        }

        public void removeAllObserver(object target)
        {
            if (target == null)
                return;
#if Cache
            HashSet<string> targetKeys;
