using System;

namespace DayZ
{
    public class NotificationObserver
    {
        public object Target { get; private set; }
        public Action<object> Selector { get; private set; }
        public string Name { get; private set; }
        public object Sender { get; private set; }

        public NotificationObserver(object target, Action<object> selector, string name, object sender)
        {
            this.Target = target;
            this.Selector = selector;
            this.Sender = sender;
            this.Name = name;
        }

        ~NotificationObserver() { }

        public void performSelector(object sender)
        {
            if (this.Target != null)
            {
                this.Selector(sender != null ? sender : this.Sender);
            }
        }

        public void release()
        {
            this.Target = null;
            this.Selector = null;
            this.Sender = null;
            this.Name = null;
        }
    }
}

