using UnityEngine;
using System.Collections;
using System.Collections.Generic;
using System;

namespace DayZ
{
    public class CoroutineManager : SingletonMono<CoroutineManager>
    {
        public static Coroutine StartCoroutineTask(IEnumerator routine)
        {
            return Instance.StartCoroutine(routine);
        }

        public static IEnumerator<float> StartCoroutineTask(IEnumerator<float> routine, Segment timing = Segment.Update)
        {
            IEnumerator<float> etor = Timing.RunCoroutine(routine, timing);
            //Timing要在Segement中调用, 原始Coroutine是立即执行，故此处强制执行一次，但是会导致yield return 0f被执行掉。
            etor.MoveNext();
            return etor;
        }

        private static IEnumerator<float> StartInnerCoroutine(IEnumerator<float> routine, Action<object> callback)
        {
            yield return Timing.WaitUntilDone(routine);
            callback(routine.Current);
        }

        /**
         * Will cast routine Current  pass to onBeginClose
         */
        public static void StartCoroutineTask(IEnumerator<float> routine, Action<object> callback)
        {
            StartCoroutineTask(StartInnerCoroutine(routine, callback));
        }

        public static void StopCoroutineTask(IEnumerator<float> routine)
        {
            Timing.KillCoroutines(routine);
        }

        public static void StopAllCoroutineTask()
        {
            Timing.KillAllCoroutines();
        }
    }
}

