#if UNITY_EDITOR || UNITY_STANDALONE_WIN
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using System.IO;
using System.Text;
using DayZ;

public class AccountSelectView : MonoBehaviour
{
    private readonly string ACCOUNT_FOLDER_NAME = "ArchivedList";
    private readonly string GAME_SCENE = "main";
    private readonly string FILE_NAME = "ArchivedData.json";
    private readonly string FILE_EXTENSION = ".json";
    private readonly string FILE_START = "ArchivedData_";
    private readonly string NEW_ACCOUNT_NAME = "现网新账号";
    private static   string DEFAULT_CONTENT = "\"ServerListAddress\": \"http://kingdomlist.warworldgames.com\"";
    private readonly string DEFAULT_CONTENT_LANG = "\"Language\": \"Icelandic\",";
    private List<KeyValuePair<string, int>> accounts = new List<KeyValuePair<string, int>>();

    public GameObject saveComponent;
    public GameObject prefab;
    public InputField saveInput;
    public Text saveTip;
    public Toggle autoClearButton;

    private void Awake() 
    {

#if !UNITY_EDITOR && UNITY_STANDALONE_WIN
        Screen.SetResolution(540, 960, false);
#endif
        DayZ.Container.Instance.InitApp();
        BestHTTP.HTTPManager.Setup();    
    }

    private void Start() 
    {
        if (CCCommonUtils.IsRedAlert())
        {
            DEFAULT_CONTENT = "\"ServerListAddress\": \"http://red2list.cloudfacy.com\"";
        }

        if (CCCommonUtils.isGtaGang2())
        {
            DEFAULT_CONTENT = "\"ServerListAddress\": \"http://citylist.sopll.com\"";
        }

        var parent = prefab.transform.parent;
        var childCount = parent.childCount;
        for (int i = childCount - 1; i >= 0; i--)
        {
            if (parent.GetChild(i).gameObject.activeSelf)
                Destroy(parent.GetChild(i).gameObject);
        }
        accounts.Clear();

        if (!File.Exists(FILE_NAME))
        {
            File.WriteAllText(FILE_NAME, GetOnlineSave());
        }

        if (!Directory.Exists(ACCOUNT_FOLDER_NAME))
        {
            Directory.CreateDirectory(ACCOUNT_FOLDER_NAME);
        }

        foreach (var item in Directory.GetFiles(ACCOUNT_FOLDER_NAME, "*.json", SearchOption.TopDirectoryOnly))
        {
            var fileInfo = new FileInfo(item);
            if (fileInfo.Name.StartsWith(FILE_START))
            {
                accounts.Add(new KeyValuePair<string, int>(fileInfo.Name.Replace(FILE_START, string.Empty).Replace(FILE_EXTENSION, string.Empty), 1));
            }
        }
#if !UNITY_EDITOR && UNITY_STANDALONE_WIN
        accounts.Add(new KeyValuePair<string, int>(NEW_ACCOUNT_NAME, 0));
        saveComponent.SetActive(true);
#endif
        this.RefreshView();
    }

    private void RefreshView()
    {
        foreach (var item in accounts)
        {
            var cell = GameObject.Instantiate(prefab, Vector3.zero, Quaternion.identity, prefab.transform.parent);
            cell.SetActive(true);
            var text = cell.GetComponentInChildren<Text>();
            text.text = item.Key;
            text.color = item.Value == 0 ? Color.green : Color.black;
        }
    }

    public void RefreshList()
    {
        Start();
    }

    public void OnClickItem(Text text)
    {
        string name = text.text;
        if (name.Equals(NEW_ACCOUNT_NAME))
        {
            PlayerPrefs.DeleteAll();
            File.WriteAllText(FILE_NAME, GetOnlineSave());
        }
        else
        {
            File.WriteAllText(FILE_NAME, (File.ReadAllText(Path.Combine(ACCOUNT_FOLDER_NAME, FILE_START + name + FILE_EXTENSION))));
        }
        GoToLogin();
    }

    public void OnClickSaveButton()
    {
        string name = saveInput.text;
        if (string.IsNullOrEmpty(name) || string.IsNullOrEmpty(string.Concat(name)) || name.Contains("_"))
        {
            saveTip.text = "请输入保存的文件名，不要为空或者有_下划线";
        }
        else
        {
            string filePath = Path.Combine(ACCOUNT_FOLDER_NAME, FILE_START + name + FILE_EXTENSION);
            File.WriteAllText(filePath, GetOnlineSave(true));
            RefreshList();
            saveTip.text = "保存成功: " + filePath;
        }
    }

    public void OnClickClearButton()
    {
        PlayerPrefs.DeleteAll();
    }

    public void OnClickOldButton()
    {
        GoToLogin();
    }

