using DayZ;

public class GSCommandPush
{
    public static bool HandleResponse(CCDictionary dict)
    {
#if GS_TOOL
        string cmd = dict.valueForKey("cmd");
        CCDictionary vparams = Global._dict(dict.objectForKey("params"));

        if (cmd.Equals("push.gs.command"))
        {
            string message = vparams.valueForKey("CommandMessage");
            CCSafeNotificationCenter.sharedNotificationCenter().postNotification(GSGlobal.LISTEN_KEY, message);
            return true;
        }
#endif

        return false;
    }
}

public class GSSendCommand : CommandBase
{
    public GSSendCommand(int sIndex, int tIndex, string command) : base("gs.command.send")
    {
        putParam("sourceIndex", sIndex);
        putParam("targetIndex", tIndex);
        putParam("command", command);
    }

    public override bool handleRecieve(CCDictionary dict)
    {
        GameController.getInstance().removeWaitInterface();
        if (dict == null)
            return false;

        CCDictionary param = dict.objectForKey("params") as CCDictionary;

        if (param == null)
            return false;

        string errorCode = param.valueForKey("errorCode");
        if (!string.IsNullOrEmpty(errorCode))
        {
            CCCommonUtils.flyHint("", "", (Global._lang(errorCode)), (int)FlyType.FLYHINT_PUNISH);
        }
        else
        {
            CCCommonUtils.FlyTip("命令发送成功");
        }

        return true;
    }
}

