using DayZ;
using System.Collections.Generic;
using System.Reflection;
using UnityEngine;
using UnityEngine.UI;

public class GSToolView : MonoBehaviour 
{   
    public Text messageLabel;
    public Button clearButton;
    public Button selectButton;

    private string PATH;
    private PropertyInfo getInst;
    private System.Type t;

#if GS_TOOL
    private void Awake() 
    {
        PATH = System.IO.Path.Combine(Application.dataPath, "../GSTool/InstructionCollecter.dll");
        CCSafeNotificationCenter.sharedNotificationCenter().addObserver(this, OnMessage, GSGlobal.LISTEN_KEY, null);
        this.CheckButtonState();
        this.ConstructMethod();
    }

    private void OnDestroy() 
    {
        CCSafeNotificationCenter.sharedNotificationCenter().removeObserver(this, GSGlobal.LISTEN_KEY);
    }

    private void OnMessage(object o)
    {
        var str = o as string;
        if (!string.IsNullOrEmpty(str))
        {
            messageLabel.text = str;
        }
        else
        {
            messageLabel.text = string.Empty;
        }
    }

    private WorldCityInfo sourceCityInfo;
    private WorldCityInfo targetCityInfo;

    public void SetSourceCity(WorldCityInfo cityInfo)
    {
        this.sourceCityInfo = cityInfo;
        this.OnMessage(GetTip());
        this.CheckButtonState();
    }

    public void SetTargetCity(WorldCityInfo cityInfo)
    {
        this.targetCityInfo = cityInfo;
        this.OnMessage(GetTip());
        this.CheckButtonState();
    }

    public void OnClickClearButton()
    {
        this.sourceCityInfo = null;
        this.targetCityInfo = null;
        this.OnMessage(string.Empty);
        this.CheckButtonState();
    }

    public void OnClickSelectButton()
    {
        GSCommandSelectView.Create(sourceCityInfo.getCityIndex(), targetCityInfo.getCityIndex(), CalcCommands());
    }

    private void ConstructMethod()
    {
        Assembly assembly = Assembly.LoadFile(PATH);
        this.t = assembly.GetType("DayZ.InstructionCollecter");
        this.getInst = t.BaseType.GetProperty("Instance", BindingFlags.Public | BindingFlags.Static | BindingFlags.GetProperty);
    }

    private List<string> CalcCommands()
    {
        object obj = getInst.GetValue(null);
        MethodInfo collectMed = t.GetMethod("ColelctInstructionList", BindingFlags.Public | BindingFlags.Instance);
        return (System.Collections.Generic.List<string>)collectMed.Invoke(obj, new object[] { this.sourceCityInfo, this.targetCityInfo });
    }

    private void CheckButtonState()
    {
        this.clearButton.gameObject.SetActive(this.sourceCityInfo != null || this.targetCityInfo != null);
        this.selectButton.gameObject.SetActive(this.sourceCityInfo != null && this.targetCityInfo != null);
    }

    private string GetTip()
    {
        return string.Format("攻击者：{0}，目标点：{1}", GetWorldCityInfoTip(sourceCityInfo),  GetWorldCityInfoTip(targetCityInfo));
    }

    private string GetWorldCityInfoTip(WorldCityInfo info)
    {
        return info == null ? "未设置" : string.Format("{0}({1})", info.getCityTilePoint(), info.getCityType());
    }
#endif
}

