using System.Collections.Generic;
using FairyGUI;
using DayZ;

public class GSCommandSelectView : PopupBaseView, IReusePanel
{
    private int sourceIndex;
    private int targetIndex;
    private List<string> commands;

    private GTextField tips;
    private GList list;

    public static GSCommandSelectView Create(int sourceIndex, int targetIndex, List<string> commands)
    {
        return PopupViewController.getInstance().CreatePopupView<GSCommandSelectView>("GSCommandSelectView", sourceIndex, targetIndex, commands);
    }

    public override void InitializeFairyComponents()
    {
        base.InitializeFairyComponents();

        this.tips = _mainView.GetChild("n1").asTextField;
        this.list = _mainView.GetChild("n2").asList;
        this.list.itemRenderer = ListItemRender;
        this.list.onClickItem.Add(OnClickListItem);

        _mainView.GetChildByPath("frame.title").asTextField.text = "请选择要执行的命令";
        _mainView.GetChildByPath("frame.btn_close").asButton.onClick.Add(closeSelf);
    }

    private void OnClickListItem(EventContext context)
    {
        int index = list.ChildIndexToItemIndex(list.GetChildIndex(context.data as GObject));
        GameController.getInstance().showWaitInterface();
        new GSSendCommand(sourceIndex, targetIndex, this.commands[index]).sendAndRelease();
        this.closeSelf();
    }

    public override void Init(params object[] data)
    {
        base.Init(data);

        sourceIndex = (int)data[0];
        targetIndex = (int)data[1];
        commands = data[2] as List<string>;

        list.numItems = commands.Count;

        var sInfo = WorldController.getInstance().getWorldCityInfo((uint)sourceIndex);
        var tInfo = WorldController.getInstance().getWorldCityInfo((uint)targetIndex);

        this.tips.text = GetTip(sInfo, tInfo);
    }

    private void ListItemRender(int index, GObject obj)
    {
        (obj as GButton).title = commands[index];
    }

    public void Reset()
    {
    }

    private string GetTip(WorldCityInfo sourceCityInfo, WorldCityInfo targetCityInfo)
    {
        return string.Format("攻击者：{0}，目标点：{1}", GetWorldCityInfoTip(sourceCityInfo),  GetWorldCityInfoTip(targetCityInfo));
    }

    private string GetWorldCityInfoTip(WorldCityInfo info)
    {
        return info == null ? "未设置" : string.Format("{0}({1})", info.getCityTilePoint(), info.getCityType());
    }
}

