using System;
using System.Runtime.CompilerServices;
using UnityEngine;

[assembly: InternalsVisibleTo("UIModule.ViewModules")]
namespace UIModule.Architecture
{
    public sealed class UIModuleManager
    {

#region 单例
        private static UIModuleManager _instance = null;

        public static UIModuleManager Instance 
        {
            get 
            {
                if (_instance == null)
                    _instance = new UIModuleManager();

                return _instance;
            }
        }
#endregion

#region  通知模块
        private INotification notification;

        public void RegisterNotification(INotification notification)
        {
            this.notification = notification;
        }

        internal void PostEvent(string eventKey, object obj = null)
        {
            if (this.notification != null)
            {
                this.notification.PostEvent(eventKey, obj);
            }
        }

        internal void AddListener(string eventKey, Action<object> callback)
        {
            if (this.notification != null)
            {
                this.notification.AddListener(eventKey, callback);
            }
        }

        internal void RemoveListener(string eventKey)
        {
            if (this.notification != null)
            {
                this.notification.RemoveListener(eventKey);
            }
        }
#endregion

#region GameObject加载模块
        private IResourceLoader resourceLoader;

        public void RegisterResourceLoader(IResourceLoader resourceLoader)
        {
            this.resourceLoader = resourceLoader;
        }

        internal GameObject Load(string name, float size = 1)
        {
            return this.resourceLoader.Load(name, size);
        }
        internal void Release(GameObject obj, string name = null)
        {
            this.resourceLoader.Release(obj, name);
        }
#endregion
        public void ModelChangeEvent(Type type)
        {
            ViewModelContainer.ModelChangeEvent(type);
        }

        public void ModelChangeEvent(string type)
        {
            ViewModelContainer.ModelChangeEvent(Type.GetType(type));
        }

        public void ModelChangeEvent<T>() where T : IComponentModel
        {
            ViewModelContainer.ModelChangeEvent(typeof(T));
        }

    }
}

