using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;

namespace UIModule.Architecture
{
    /// <summary>
    /// UIModule架构中ViewModel对象的创建工厂
    /// </summary>
    public class ViewModelFactory
    {
        private static Dictionary<Type, IViewModelFactory> factory;

        internal static IViewModelFactory Get<T>() where T : IComponentModel
        {
            return Get(typeof(T));
        }

        internal static IViewModelFactory Get(Type type)
        {
            CheckAssemblyFactory();
            return factory[type];
        }

        public static T Create<T>(params object[] param) where T : IComponentModel, new()
        {
            T result = new T();
            result.InitContext(param);
            Get<T>()?.PrepareModel(result);
            return result;
        }

        private static void CheckAssemblyFactory()
        {
            if (factory != null)   
                return;

            factory = new Dictionary<Type, IViewModelFactory>();
            foreach (var assembly in AppDomain.CurrentDomain.GetAssemblies())
            {
                foreach(var type in assembly.GetExportedTypes().Where(type => type.IsDefined(typeof(UIModuleFactoryAttribute), false)))
                {
                    factory.Add(type.BaseType.GenericTypeArguments[0], Activator.CreateInstance(type) as IViewModelFactory);
                }
            }
        }
    }
}

