using System;
using System.Collections.Generic;

namespace UIModule.Architecture
{
    public abstract class IComponentModel
    {
        internal protected virtual void InitContext(params object[] param) { }
        internal bool Dirty { get; set; }

        internal void Refresh()
        {
            ViewModelFactory.Get(this.GetType()).PrepareModel(this);
            this.Dirty = false;
        }

        protected internal virtual List<KeyValuePair<string, Action<object>>> Listeners { get; }

        internal virtual void AddListener() 
        {
            if (this.Listeners.Count > 0)
            {
                foreach (var item in this.Listeners)
                {
                    UIModuleManager.Instance.AddListener(item.Key, item.Value);
                }
            }
        }

        internal virtual void RemoveListener() 
        {
            if (this.Listeners.Count > 0)
            {
                foreach (var item in this.Listeners)
                {
                    UIModuleManager.Instance.RemoveListener(item.Key);
                }
            }
        }
    }
}

