using System;
using System.Collections.Generic;

namespace UIModule.Architecture
{
    internal class ViewModelContainer
    {
        private static Dictionary<Type, IComponentModel> viewModelCache = new Dictionary<Type, IComponentModel>();

        internal static IComponentModel Get<T>(params object[] param) where T : IComponentModel
        {
            return Get(typeof(T), param);
        }

        internal static IComponentModel Get(Type type, params object[] param)
        {
            IComponentModel result = null;
            if (!viewModelCache.TryGetValue(type, out result))
            {
                result = Activator.CreateInstance(type) as IComponentModel;
                result.AddListener();
                viewModelCache.Add(type, result);
            }
            result.InitContext(param);
            ViewModelFactory.Get(type)?.PrepareModel(result);
            return result;
        }

        internal static void ModelChangeEvent(Type type)
        {
            if (viewModelCache.TryGetValue(type, out var result))
            {
                result.Dirty = true;
            }
        }

        internal static void Release<T>(T viewModel) where T : IComponentModel
        {
            if (viewModel != null)
            {
                viewModel.RemoveListener();
            }
            viewModelCache.Remove(typeof(T));
        }
    }
}

