using System;
using System.Collections.Generic;
using UnityEngine;
using System.Text;
using System.Linq;

namespace DayZ
{
    public static class ObjectPoolUtility
    {

        #region List
        public static List<T> GetListObject<T>()
        {
            return ListPool<T>.GetListObject();
        }

        /// <summary>
        /// 
        /// </summary>
        /// <param name="self"></param>
        /// <typeparam name="T"></typeparam>
        public static void Release2Pool<T>(this List<T> target)
        {
            ListPool<T>.Recycle(target);
        }
        #endregion


        #region Dictionary
        public static Dictionary<TKey, TValue> GetDictionaryObject<TKey, TValue>()
        {
            return DictionaryPool<TKey, TValue>.GetDictionaryObject();
        }

        /// <summary>
        /// 对字典拓展 自身入栈 的方法
        /// </summary>
        /// <param name="toRelease"></param>
        public static void RecycleDictionary<TKey, TValue>(this Dictionary<TKey, TValue> target)
        {
            DictionaryPool<TKey, TValue>.Recycle(target);
        }
        #endregion


        #region WorldCityInfo

        /// <summary>
        /// this.GetWorldCityInfoObject();
        /// </summary>
        /// <param name="user"></param>
        public static WorldCityInfo GetWorldCityInfoObject(this object user)
        {
            return ObjectPoolManager.Instance.GetReusableObject<WorldCityInfo>(user);
        }

        /// <summary>
        /// 对字典拓展 自身入栈 的方法
        /// </summary>
        /// <param name="toRelease"></param>
        public static void RecycleWorldCityInfoObject(this WorldCityInfo target)
        {
            ObjectPoolManager.Instance.RecycleReusableObject(target);
        }
        #endregion
    }
}

