using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;
using UnityEngine;

namespace DayZ
{
    using schedule_selector = Scheduler.schedule_selector;

    public class CCNode : MonoBehaviour, ScheulerUpdateTarget
    {
        /** Default tag used for all the nodes */
        public static int INVALID_TAG = -1;
        protected static uint CC_REPEAT_FOREVER = uint.MaxValue - 1;

        // FIXME:: Yes, nodes might have a sort problem once every 15 days if the game runs at 60 FPS and each frame sprites are reordered.
        protected static int s_globalOrderOfArrival = 1;

        #region 自身的属性
        [HideInInspector]
        public SpriteRenderer _spriteRenderer;       // 用来渲染CCNode，CCSprite或者CCLayer的图片用的子节点
        private Transform _anchorTrans;
        public Transform anchorTrans
        {
            get
            {
                if (_anchorTrans == null)
                {
                    _anchorTrans = transform.Find("Anchor");
                    if(_anchorTrans == null)
                    {
                        _anchorTrans = new GameObject("Anchor").transform;
                        _anchorTrans.SetParent(gameObject.transform, false);
                    }
                }
                return _anchorTrans;
            }
        }

        public bool doNotVisit { get; set; } = false;

        public bool RecycleImmediately { get; set; } = false;

        protected CCNode _parent;                       // 父节点，和Unity里的是对应的，为了运算方法也模仿cocos写了一个
        protected CCDirector _director;
        protected int _orderOfArrival;                  // used to preserve sequence while sorting children with the same localZOrder
        protected int _localZOrder;                     // 节点的渲染顺序，等同于一部分Unity中2D的sortingOrder
        protected float _globalZOrder;                  // 全局的一个排序，目前不知道怎么用，可能等于Unity里的Layer
        protected string _name;                         // 节点的名称，和Unity保持一致，但是为了方便计算也单独提出来了
        protected int _tag;                             // 节点的tag，Unity中是string，而且Unity中的tag必须预定义好，cocos是int无法兼容
        protected List<CCNode> _children = new List<CCNode>();  // 缓存的子节点列表
        protected object _userData = null;              // void*
        protected object _userObject = null;            // Ref*
        protected int _innerRemoveCall = 0;
        protected int _innerAddCall = 0;
        protected bool _running = false;
        protected bool _isTransitionFinished = false;   // flag to indicate whether the transition was finished
        protected bool _reorderChildDirty = false;

        protected Action _onEnterCallback = null;
        protected Action _onExitCallback = null;
        protected Action _onEnterTransitionDidFinishCallback = null;
        protected Action _onExitTransitionDidStartCallback = null;

        protected byte _displayedOpacity = 255;
        protected byte _realOpacity = 255;
        protected Color32 _displayedColor = Color.white;
        protected Color32 _realColor = Color.white;
        protected bool _cascadeColorEnabled;
        protected bool _cascadeOpacityEnabled;
        protected Scheduler _scheduler = null;
        protected CCActionManager _actionManager = null;

        protected Vector2 _anchorPointInPoints = Vector2.zero;
        protected Vector2 _anchorPoint = Vector2.zero;
        protected bool _ignoreAnchorPointForPosition = false;
        protected Vector2 _contentSize = Vector2.zero;
        protected CCRect _touchMargin = new CCRect();

        protected Vector2 _normalizedPosition;
        protected bool _usingNormalizedPosition;

        protected float _skewX;
        protected float _skewY;
#endregion

#region 一部分自身属性的一些get/set方法
        public virtual int getTag()
        {
            return _tag;
        }

        public virtual void setTag(int tag)
        {
            _tag = tag;
        }

        public virtual string getName()
        {
            return _name;
        }

        public virtual void setName(string name)
        {
            _name = name;
            this.gameObject.name = name;
        }

        public virtual object getUserData() { return _userData; }

        public virtual void setUserData(object userData)
        {
            this._userData = userData;
        }

        public virtual object getUserObject() { return _userObject; }

        public virtual void setUserObject(object userObject)
        {
            _userObject = userObject;
        }

        public virtual void setParent(CCNode parent)
        {
            _parent = parent;
            //_transformUpdated = _transformDirty = _inverseDirty = true;
            // Unity模拟逻辑

            if (parent == null)
            {
                try
                {
                    this.transform.SetParent(CCNodeCache.Instance.poolsParent.transform, false);
                    if (this.RecycleImmediately)
                        CCNodeCache.Instance.RecycleCCNode(this);
                    else
                        CCNodeCache.Instance.deleteQueue.Enqueue(this);
                }
                catch (MissingReferenceException)
                {
                    // Debug.LogError("出错：" + stackMessage);
                }
            }
            else
            {
                this.transform.SetParent(parent.anchorTrans, false);
            }
        }

        public virtual CCNode getParent() { return _parent; }

