namespace DayZ
{
    public class CCAction
    {
        protected CCNode _originalTarget;
        protected CCNode _target;
        protected int _tag;

        public const int INVALID_TAG = -1;

        public virtual string description()
        {
            return string.Format("<Action | Tag = {0}", _tag);
        }

        protected virtual CCAction _clone() { return null; }

        protected virtual CCAction _reverse() { return null; }

        public CCAction clone() { return _clone(); }

        public CCAction reverse() { return _reverse(); }

        public virtual bool isDone() { return true; }

        public virtual void startWithTarget(CCNode target)
        {
            _originalTarget = _target = target;
        }

        public virtual void stop() { _target = null; }

        public virtual void step(float dt) { }

        public virtual void update(float time) { }

        public CCNode getTarget() { return _target; }

        public void setTarget(CCNode target) { _target = target; }

        public CCNode getOriginalTarget() { return _originalTarget; }

        public void setOriginalTarget(CCNode originalTarget) { _originalTarget = originalTarget; }

        public int getTag() { return _tag; }

        public void setTag(int tag) { _tag = tag; }

        protected CCAction()
        {
            _originalTarget = null;
            _target = null;
            _tag = INVALID_TAG;
        }
    }
}
